func median(a []float64) float64 {
    if len(a) == 0 { return math.NaN() }
    b := append([]float64(nil), a...)
    sort.Float64s(b)
    n := len(b)
    if n%2 == 1 { return b[n/2] }
    return (b[n/2-1] + b[n/2]) / 2
}

import "math"

func stdev(a []float64) float64 {
    n := len(a)
    if n < 2 { return math.NaN() }
    m := mean(a)
    s := 0.0
    for _, x := range a { d := x - m; s += d * d }
    return math.Sqrt(s / float64(n-1))
}

