// Dijkstra with min-heap
import "container/heap"

type pair struct{ d, u int }

type minHeap []pair
func (h minHeap) Len() int { return len(h) }
func (h minHeap) Less(i, j int) bool { return h[i].d < h[j].d }
func (h minHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }
func (h *minHeap) Push(x any) { *h = append(*h, x.(pair)) }
func (h *minHeap) Pop() any { old := *h; n := len(old); x := old[n-1]; *h = old[:n-1]; return x }

func dijkstra(n int, adj [][][2]int, src int) []int {
    const INF = int(1e9)
    dist := make([]int, n)
    for i := range dist { dist[i] = INF }
    dist[src] = 0
    h := &minHeap{}
    heap.Init(h)
    heap.Push(h, pair{0, src})
    for h.Len() > 0 {
        p := heap.Pop(h).(pair)
        d, u := p.d, p.u
        if d != dist[u] { continue }
        for _, e := range adj[u] { v, w := e[0], e[1]; nd := d + w; if nd < dist[v] { dist[v] = nd; heap.Push(h, pair{nd, v}) } }
    }
    return dist
}

