import "sort"

type dsu struct{ p, r []int }
func newDSU(n int) *dsu { p:=make([]int,n); r:=make([]int,n); for i:=0;i<n;i++{p[i]=i}; return &dsu{p,r} }
func (d *dsu) find(x int) int { if d.p[x]==x { return x }; d.p[x]=d.find(d.p[x]); return d.p[x] }
func (d *dsu) unite(a,b int) bool { a=d.find(a); b=d.find(b); if a==b { return false }; if d.r[a]<d.r[b] { a,b=b,a }; d.p[b]=a; if d.r[a]==d.r[b] { d.r[a]++ }; return true }

func kruskalMST(n int, edges [][3]int) int {
    sort.Slice(edges, func(i,j int){ return edges[i][2] < edges[j][2] })
    d := newDSU(n)
    total, cnt := 0, 0
    for _, e := range edges { if d.unite(e[0], e[1]) { total += e[2]; cnt++; if cnt==n-1 { break } } }
    if cnt != n-1 { return -1 }
    return total
}

// edges: [u,v,w]
func bellmanFord(n int, edges [][3]int, src int) ([]int, bool){
    const INF = int(1e9)
    dist := make([]int, n)
    for i:=range dist { dist[i]=INF }
    dist[src]=0
    for i:=1; i<=n-1; i++ {
        updated := false
        for _, e := range edges { u,v,w := e[0], e[1], e[2]; if dist[u]!=INF && dist[u]+w<dist[v] { dist[v]=dist[u]+w; updated=true } }
        if !updated { break }
    }
    for _, e := range edges { u,v,w := e[0], e[1], e[2]; if dist[u]!=INF && dist[u]+w<dist[v] { return dist, true } }
    return dist, false
}

func topoSortKahn(n int, adj [][]int) []int {
    indeg := make([]int, n)
    for u:=0; u<n; u++ { for _, v := range adj[u] { indeg[v]++ } }
    q := make([]int,0)
    for i:=0;i<n;i++ { if indeg[i]==0 { q = append(q,i) } }
    order := make([]int,0,n)
    for h:=0; h<len(q); h++ { u := q[h]; order = append(order,u); for _, v := range adj[u] { indeg[v]--; if indeg[v]==0 { q = append(q,v) } } }
    return order
}

func kmpSearch(text, pat string) []int {
    n, m := len(text), len(pat)
    if m==0 { return []int{} }
    lps := make([]int, m)
    for i, l := 1, 0; i < m; { if pat[i]==pat[l] { lps[i]=l+1; i++; l++; } else if l>0 { l=lps[l-1] } else { lps[i]=0; i++; } }
    res := []int{}
    for i, j := 0, 0; i < n; { if text[i]==pat[j] { i++; j++; if j==m { res = append(res, i-m); j=lps[j-1] } } else if j>0 { j=lps[j-1] } else { i++ } }
    return res
}

func rabinKarp(text, pat string) []int {
    n, m := len(text), len(pat)
    if m==0 || m>n { return []int{} }
    const B, MOD = 131, 1000000007
    powB := 1
    for i:=0; i<m-1; i++ { powB = (powB*B)%MOD }
    hpat, hwin := 0, 0
    for i:=0; i<m; i++ { hpat=(hpat*B+int(pat[i]))%MOD; hwin=(hwin*B+int(text[i]))%MOD }
    out := []int{}
    for i:=0; i<=n-m; i++ {
        if hpat==hwin && text[i:i+m]==pat { out = append(out, i) }
        if i<n-m { hwin = ((hwin - int(text[i])*powB)%MOD + MOD)%MOD; hwin = (hwin*B + int(text[i+m]))%MOD }
    }
    return out
}

func sieveIsPrime(n int) []bool {
    is := make([]bool, n+1)
    for i:=range is { is[i]=true }
    if n>=0 { is[0]=false }
    if n>=1 { is[1]=false }
    for p:=2; p*p<=n; p++ { if is[p] { for x:=p*p; x<=n; x+=p { is[x]=false } } }
    return is
}

func editDistance(a, b string) int {
    m, n := len(a), len(b)
    prev := make([]int, n+1)
    cur := make([]int, n+1)
    for j:=0; j<=n; j++ { prev[j]=j }
    for i:=1; i<=m; i++ {
        cur[0]=i; ai:=a[i-1]
        for j:=1; j<=n; j++ {
            cost := 0; if ai!=b[j-1] { cost=1 }
            del:=prev[j]+1; ins:=cur[j-1]+1; rep:=prev[j-1]+cost
            cur[j]=min3(del,ins,rep)
        }
        prev,cur = cur,prev
    }
    return prev[n]
}
func min3(a,b,c int) int { if a<b { if a<c { return a }; return c } else { if b<c { return b }; return c } }

func lisLength(a []int) int {
    tails := make([]int, 0, len(a))
    for _, x := range a {
        i := lowerBound(tails, x)
        if i==len(tails) { tails = append(tails, x) } else { tails[i]=x }
    }
    return len(tails)
}
func lowerBound(a []int, x int) int {
    l, r := 0, len(a)
    for l<r { m:=(l+r)/2; if a[m]>=x { r=m } else { l=m+1 } }
    return l
}

func quickselect(a []int, k int) int { // k: 1-based
    l, r := 0, len(a)-1; k--
    for l<=r {
        pivot := a[r]; i := l
        for j:=l; j<r; j++ { if a[j]<=pivot { a[i],a[j]=a[j],a[i]; i++ } }
        a[i],a[r]=a[r],a[i]
        if i==k { return a[i] } else if i>k { r=i-1 } else { l=i+1 }
    }
    panic("k out of range")
}

func binarySearchInt(a []int, target int) int {
    l, r := 0, len(a)-1
    for l <= r {
        m := (l + r) / 2
        if a[m] == target { return m }
        if a[m] < target { l = m + 1 } else { r = m - 1 }
    }
    return -1
}

func mergeSortInt(a []int) []int {
    n := len(a)
    if n <= 1 { return append([]int(nil), a...) }
    m := n/2
    left := mergeSortInt(a[:m])
    right := mergeSortInt(a[m:])
    return mergeInt(left, right)
}
func mergeInt(a, b []int) []int {
    res := make([]int, 0, len(a)+len(b))
    i, j := 0, 0
    for i < len(a) && j < len(b) {
        if a[i] <= b[j] { res = append(res, a[i]); i++ } else { res = append(res, b[j]); j++ }
    }
    res = append(res, a[i:]...)
    res = append(res, b[j:]...)
    return res
}

type Fenwick struct {
    n int
    t []int
}
func NewFenwick(n int) Fenwick { return Fenwick{ n: n, t: make([]int, n+1) } }
func (f *Fenwick) Add(i, delta int) {
    for i += 1; i <= f.n; i += i & -i { f.t[i] += delta }
}
func (f *Fenwick) Sum(i int) int { // sum of [0..i]
    s := 0
    for i += 1; i > 0; i -= i & -i { s += f.t[i] }
    return s
}
func (f *Fenwick) RangeSum(l, r int) int { if r < l { return 0 }; return f.Sum(r) - f.Sum(l-1) }

func bfsDist(n int, adj [][]int, src int) []int {
    dist := make([]int, n)
    for i:=range dist { dist[i] = -1 }
    q := make([]int, 1, n)
    q[0] = src
    dist[src] = 0
    for h:=0; h<len(q); h++ {
        u := q[h]
        for _, v := range adj[u] {
            if dist[v] == -1 { dist[v] = dist[u] + 1; q = append(q, v) }
        }
    }
    return dist
}

