import "container/list"

func zeroOneBFS(n int, adj [][][2]int, src int) []int {
    const INF = int(1e9)
    dist := make([]int, n)
    for i:=range dist { dist[i]=INF }
    dist[src]=0
    dq := list.New()
    dq.PushBack(src)
    for dq.Len() > 0 {
        front := dq.Front(); dq.Remove(front)
        u := front.Value.(int)
        for _, e := range adj[u] { v, w := e[0], e[1]
            if dist[u]+w < dist[v] {
                dist[v] = dist[u]+w
                if w==0 { dq.PushFront(v) } else { dq.PushBack(v) }
            }
        }
    }
    return dist
}

// dist is n x n matrix; use a big INF for no edge
func floydWarshall(dist [][]int) [][]int {
    n := len(dist)
    d := make([][]int, n)
    for i:=0;i<n;i++ { d[i] = append([]int(nil), dist[i]...) }
    for k:=0;k<n;k++ {
        for i:=0;i<n;i++ { if d[i][k] == int(1e9) { continue }
            for j:=0;j<n;j++ { if d[k][j] == int(1e9) { continue }
                if nd := d[i][k] + d[k][j]; nd < d[i][j] { d[i][j] = nd }
            }
        }
    }
    return d
}

func prefixSums(a []int) []int {
    ps := make([]int, len(a)+1)
