    return ps
}

func lengthOfLongestSubstring(s string) int {
    last := make(map[byte]int)
    best, l := 0, 0
    for r := 0; r < len(s); r++ {
        if idx, ok := last[s[r]]; ok && idx >= l { l = idx + 1 }
        last[s[r]] = r
        if cur := r - l + 1; cur > best { best = cur }
    }
    return best
}

func modPow(a, e, m int64) int64 {
    a %= m
    if a < 0 { a += m }
    res := int64(1)
    for e > 0 {
        if e & 1 == 1 { res = (res * a) % m }
        a = (a * a) % m
        e >>= 1
    }
    return res
}

func egcd(a, b int64) (g, x, y int64) {
    if b == 0 { return a, 1, 0 }
    g1, x1, y1 := egcd(b, a%b)
    return g1, y1, x1 - (a/b)*y1
}
func modInverse(a, m int64) int64 {
    g, x, _ := egcd(a, m)
    if g != 1 && g != -1 { return -1 }
    x %= m
    if x < 0 { x += m }
    return x
}
